def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for color in set(v for row in grid for v in row):
        if color == grid[0][0]:
            continue
        for dr, dc in ((1,1),(1,-1)):
            for r in range(h):
                for c in range(w):
                    prev_r, prev_c = r-dr, c-dc
                    if 0 <= prev_r < h and 0 <= prev_c < w and grid[prev_r][prev_c] == color:
                        continue
                    run=[]; rr,cc=r,c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr,cc)); rr+=dr; cc+=dc
                    if len(run) >= 3:
                        rr,cc=r-dr,c-dc
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] == grid[0][0]: out[rr][cc]=color
                            rr-=dr; cc-=dc
    return out
